#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Protocol version 1, revision 1.  Reads one JSON document on stdin, writes one
JSON document on stdout.  Exit status is always 0.
"""

import itertools
import json
import math
import re
import sys

MAX_INPUT_BYTES = 4194304
MAX_OUTPUT_BYTES = 16777216
MAX_ASN = 4294967295
MAX_COUNT = 1000000
MAX_RIB = 2000
MAX_PRIORS = 2000
MAX_DECLARED = 2000
MAX_QUERIES = 512
MAX_IXPS = 1024
MAX_RAW_PATH = 64
MAX_RIB_TOTAL = 40000
MAX_RIB_LINKS = 4096
MAX_CORE_LINKS = 64
MAX_ORDER_LEN = 5000
MAX_NEIGHBORS = 4

TOP_KEYS = ('version', 'ixps', 'rib', 'priors', 'declared', 'order', 'queries')
C2P, P2P, P2C = 0, 1, 2
STATES = (C2P, P2P, P2C)
REL_STATE = {'c2p': C2P, 'p2p': P2P, 'p2c': P2C}
# g(L, R): preferred centre type for a centre whose context is (L, R).
G_TABLE = ((C2P, C2P, P2P),
           (P2P, P2P, P2C),
           (P2P, P2P, P2C))
ID_RE = re.compile(r'\A[A-Za-z0-9_.\-]{1,64}\Z')
UNIFORM = (1, 3, 1, 3, 1, 3)          # num, den triples


class Invalid(Exception):
    pass


class Broken(Exception):
    pass


# --------------------------------------------------------------------------
# input reading and JSON safety
# --------------------------------------------------------------------------
def read_all():
    stream = sys.stdin.buffer
    pieces = []
    total = 0
    limit = MAX_INPUT_BYTES + 1
    while total < limit:
        chunk = stream.read(min(1 << 16, limit - total))
        if not chunk:
            break
        pieces.append(chunk)
        total += len(chunk)
    if total >= limit:
        # Anything larger is out of domain; refuse without draining stdin.
        raise Invalid()
    return b''.join(pieces)


def object_hook(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise Broken()
        out[key] = value
    return out


def reject_float(text):
    raise Broken()


def reject_constant(text):
    raise Broken()


def parse(data):
    try:
        text = data.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid()
    try:
        return json.loads(text, object_pairs_hook=object_hook,
                          parse_float=reject_float,
                          parse_constant=reject_constant)
    except Broken:
        raise Invalid()
    except (ValueError,RecursionError, TypeError):
        raise Invalid()


# --------------------------------------------------------------------------
# typed validation helpers
# --------------------------------------------------------------------------
def expect_dict(obj):
    if type(obj) is not dict:
        raise Invalid()
    return obj


def expect_list(obj):
    if type(obj) is not list:
        raise Invalid()
    return obj


def exact_keys(obj, names):
    obj = expect_dict(obj)
    if len(obj) != len(names):
        raise Invalid()
    for name in names:
        if name not in obj:
            raise Invalid()
    return obj


def is_int(value):
    return type(value) is int


def asn(value):
    if type(value) is not int or value < 1 or value > MAX_ASN:
        raise Invalid()
    return value


def path_of(obj):
    items = expect_list(obj)
    if len(items) > MAX_RAW_PATH:
        raise Invalid()
    return [asn(v) for v in items]


def count_of(value):
    if type(value) is not int or value < 1 or value > MAX_COUNT:
        raise Invalid()
    return value


def pair_of(obj):
    items = expect_list(obj)
    if len(items) != 2:
        raise Invalid()
    u = asn(items[0])
    v = asn(items[1])
    if u == v:
        raise Invalid()
    return (u, v)


def canonical(u, v):
    return (u, v) if u < v else (v, u)


def key_dir(u, v):
    """(canonical link, sign) where sign is True for the canonical direction."""
    if u < v:
        return (u, v), True
    return (v, u), False


def normalize(raw, ixps):
    """Remove IXPs, then collapse maximal runs of adjacent duplicates."""
    out = []
    for value in raw:
        if value in ixps:
            continue
        if out and out[-1] == value:
            continue
        out.append(value)
    looped = len(set(out)) != len(out)
    return tuple(out), looped


# --------------------------------------------------------------------------
# simultaneous peripheral peeling
# --------------------------------------------------------------------------
def peel(paths):
    """paths: dict directed-path tuple -> count.  Returns (rounds, final)."""
    rounds = {}
    current = dict(paths)
    step = 0
    while current:
        step += 1
        occ = {}
        for path in current:
            prev = path[0]
            for value in path[1:]:
                occ.setdefault(canonical(prev, value), []).append(path)
                prev = value
        marked = set()
        for link, plist in occ.items():
            u, v = link
            allu = True
            allv = True
            for path in plist:
                if path[0] != u and path[-1] != u:
                    allu = False
                if path[0] != v and path[-1] != v:
                    allv = False
                if not allu and not allv:
                    break
            if allu or allv:
                marked.add(link)
        if not marked:
            break
        for link in marked:
            rounds[link] = step
        nxt = {}
        for path, count in current.items():
            head = path[0]
            second = path[1]
            penult = path[-2]
            last = path[-1]
            trimmed = path
            if canonical(head, second) in marked:
                trimmed = trimmed[1:]
            if canonical(penult, last) in marked:
                trimmed = trimmed[:-1] if len(trimmed) > 1 else trimmed[:0]
            if len(trimmed) < 2:
                continue
            nxt[trimmed] = nxt.get(trimmed, 0) + count
        current = nxt
    return rounds, current


# --------------------------------------------------------------------------
# exact core model
# --------------------------------------------------------------------------
class Model(object):
    """Joint model over the ternary variable of every canonical core link."""

    def __init__(self, finals, core_links):
        self.index = {}
        self.links = list(core_links)
        for i, link in enumerate(self.links):
            self.index[link] = i
        self.m = len(self.links)
        # per-variable bookkeeping
        self.ctx = [[] for _ in range(self.m)]     # list of (li, ri, count)
        self.scope_list = [None] * self.m
        self.strides = [None] * self.m
        self.pats = [{} for _ in range(self.m)]    # pattern key -> count
        self._collect(finals)

    def _collect(self, finals):
        index = self.index
        for path, count in finals.items():
            n = len(path)
            rev = path[::-1]
            for i in range(n - 1):
                a = path[i]
                b = path[i + 1]
                if a < b:
                    link, seq, j = (a, b), path, i
                else:
                    link, seq, j = (b, a), rev, n - 2 - i
                e = index.get(link)
                if e is None:
                    raise Invalid()
                if j > 0:
                    x = seq[j - 1]
                    li, ldir = key_dir(x, a)
                    lv = index.get(li)
                    if lv is None:
                        raise Invalid()
                    left = (lv, ldir)
                else:
                    left = None
                if j + 2 < n:
                    y = seq[j + 2]
                    ri, rdir = key_dir(b, y)
                    rv = index.get(ri)
                    if rv is None:
                        raise Invalid()
                    right = (rv, rdir)
                else:
                    right = None
                self.ctx[e].append((left, right, count))

    def _digits(self, k):
        cached = getattr(self, '_dig', None)
        if cached is None:
            cached = self._dig = {}
        got = cached.get(k)
        if got is None:
            got = cached[k] = [list(item) for item in
                               itertools.product(STATES, repeat=k)]
        return got

    def _prepare(self):
        for e in range(self.m):
            seen = [False] * self.m
            seen[e] = True
            scope = [e]
            for left, right, _count in self.ctx[e]:
                for ctx in (left, right):
                    if ctx is not None and not seen[ctx[0]]:
                        seen[ctx[0]] = True
                        scope.append(ctx[0])
            self.scope_list[e] = tuple(scope)
            k = len(scope)
            pos = {}
            for i, var in enumerate(scope):
                pos[var] = i
            self.strides[e] = pos
            table = {}
            for left, right, count in self.ctx[e]:
                dims = []
                if left is not None:
                    dims.append((pos[left[0]], left[1]))
                if right is not None:
                    dims.append((pos[right[0]], right[1]))
                for values in self._digits(len(dims)):
                    if left is None:
                        lv = C2P
                    else:
                        raw = values[0]
                        lv = raw if left[1] else 2 - raw
                    if right is None:
                        rv = P2C
                    else:
                        raw = values[-1]
                        rv = raw if right[1] else 2 - raw
                    g = G_TABLE[lv][rv]
                    key = tuple([(pos[e], g)] + list(zip(dims and [d[0] for d in dims] or [], values)))
                    table[key] = table.get(key, 0) + count
            self.pats[e] = table

    def build_phis(self):
        """Return (scope, values) per core variable; values are exact ints."""
        self._prepare()
        phis = []
        for e in range(self.m):
            scope = self.scope_list[e]
            k = len(scope)
            size = 3 ** k
            values = [0] * size
            base = [1] * k
            for pos in range(k):
                base[pos] = 3 ** (k - 1 - pos)
            digits = self._digits(k)
            free_base = [base[i] for i in range(k) if i != 0]   # e is at 0
            free_sets = [tuple(sorted(free_base[:i] + free_base[i + 1:]))
                         for i in range(1, k + 1)]
            for key, count in self.pats[e].items():
                fixed = 0
                n_fixed = 0
                for pos, value in key:
                    fixed += pos * 0            # placeholder, replaced below
                    n_fixed += 1
                # recompute with stride lookup
                fixed = 0
                for pos, value in key:
                    fixed += base[pos] * value
                used = set(pos for pos, _v in key)
                free_positions = [i for i in range(k) if i not in used]
                offsets = [0]
                for i in free_positions:
                    step = base[i]
                    offsets = [o + t * step for o in offsets for t in STATES]
                for off in offsets:
                    values[fixed + off] += count
            phis.append((scope, values))
        return phis


def build_plan(phis, order_vars):
    """Variable elimination plan; scopes only, so it is clamp independent."""
    scopes = [list(scope) for scope, _values in phis]
    alive = [True] * len(scopes)
    steps = []
    tail = []
    for var in order_vars:
        involved = []
        for fi in range(len(scopes)):
            if alive[fi] and var in scopes[fi]:
                involved.append(fi)
        if not involved:
            continue
        union = []
        for fi in involved:
            for x in scopes[fi]:
                if x not in union:
                    union.append(x)
        others = [x for x in union if x != var]
        n = len(union)
        size = 3 ** n
        digits = [list(item) for item in itertools.product(STATES, repeat=n)]
        maps = []
        for fi in involved:
            scope = scopes[fi]
            fstr = [3 ** (len(scope) - 1 - i) for i in range(len(scope))]
            pos = [union.index(x) for x in scope]
            table = []
            for d in digits:
                idx = 0
                for j, p in enumerate(pos):
                    idx += d[p] * fstr[j]
                table.append(idx)
            maps.append((fi, table))
        ostr = [3 ** (len(others) - 1 - i) for i in range(len(others))]
        opos = [union.index(x) for x in others]
        outmap = []
        for d in digits:
            idx = 0
            for j, p in enumerate(opos):
                idx += d[p] * ostr[j]
            outmap.append(idx)
        for fi in involved:
            alive[fi] = False
        scopes.append(list(others))
        steps.append((maps, outmap, size, len(others)))
    for fi in range(len(scopes)):
        if alive[fi]:
            tail.append(fi)
    return steps, tail


def run_plan(plan, phis, clamp=None):
    steps, tail = plan
    values = [list(v) for _scope, v in phis]
    if clamp is not None:
        var, state = clamp
        scope, _v = phis[var]
        pos = scope.index(var)
        stride = 3 ** (len(scope) - 1 - pos)
        table = values[var]
        size = len(table)
        for idx in range(size):
            if (idx // stride) % 3 != state:
                table[idx] = 0
    for maps, outmap, size, nother in steps:
        out = [0] * (3 ** nother)
        if len(maps) == 1:
            fi, table = maps[0]
            src = values[fi]
            for j in range(size):
                x = src[table[j]]
                if x:
                    out[outmap[j]] += x
        else:
            srcs = [values[fi] for fi, _t in maps]
            tbls = [t for _fi, t in maps]
            for j in range(size):
                prod = 1
                for k in range(len(srcs)):
                    prod *= srcs[k][tbls[k][j]]
                    if not prod:
                        break
                if prod:
                    out[outmap[j]] += prod
        values.append(out)
    result = 1
    for fi in tail:
        for x in values[fi]:
            result *= x
    return result


def infer_marginals(phis, order_vars):
    plan = build_plan(phis, order_vars)
    total = run_plan(plan, phis)
    if total == 0:
        return None
    marginals = []
    for var in range(len(phis)):
        scope = phis[var][0]
        if len(scope) == 1:
            row = phis[var][1]
            s = row[0] + row[1] + row[2]
            if s == total or len(row) != 3:
                marginals.append((row[0], row[1], row[2], s))
                continue
        sums = []
        for state in (C2P, P2P):
            sums.append(run_plan(plan, phis, (var, state)))
        rest = total - sums[0] - sums[1]
        if rest < 0:
            rest = 0
        sums.append(rest)
        marginals.append((sums[0], sums[1], sums[2], total))
    return marginals


# --------------------------------------------------------------------------
# scoring
# --------------------------------------------------------------------------
def legit(left, right):
    """U + D - U*D exactly, with U=left[0], D=right[2] as (num, den)."""
    nu, du = left[0]
    nd, dd = right[2]
    num = nu * dd + nd * du - nu * nd
    den = du * dd
    if num <= 0:
        return (0, 1)
    g = math.gcd(num, den)
    return (num // g, den // g)


def full_legitimacy(vectors):
    total_c = 1.0
    total_d = 0.0
    total_p = 0.0
    for vec in vectors:
        pc = float(vec[0][0]) / vec[0][1]
        pp = float(vec[1][0]) / vec[1][1]
        pd = float(vec[2][0]) / vec[2][1]
        nc = total_c * pc
        nd = (total_c + total_d) * pd
        np_ = total_c * pp + total_p * pd
        total_c, total_d, total_p = nc, nd, np_
    out = total_c + total_d + total_p
    if not math.isfinite(out):
        return 0.0
    if out < 0.0:
        return 0.0
    if out > 1.0:
        return 1.0
    return out


def one_hot(state, forward):
    vec = [(0, 1), (0, 1), (0, 1)]
    vec[state] = (1, 1)
    if not forward:
        vec = [vec[2], vec[1], vec[0]]
    return tuple(vec)


def solve(document):
    # ---------------- schema ----------------
    obj = expect_dict(document)
    if len(obj) != len(TOP_KEYS):
        raise Invalid()
    for name in TOP_KEYS:
        if name not in obj:
            raise Invalid()
    version = obj['version']
    if type(version) is not int or version != 1:
        raise Invalid()

    raw_ixps = expect_list(obj['ixps'])
    if len(raw_ixps) > MAX_IXPS:
        raise Invalid()
    ixps = set()
    for value in raw_ixps:
        v = asn(value)
        if v in ixps:
            raise Invalid()
        ixps.add(v)

    raw_rib = expect_list(obj['rib'])
    if len(raw_rib) > MAX_RIB:
        raise Invalid()
    rib_records = []
    total_len = 0
    for record in raw_rib:
        item = exact_keys(record, ('path', 'count'))
        path = path_of(item['path'])
        total_len += len(path)
        if total_len > MAX_RIB_TOTAL:
            raise Invalid()
        rib_records.append((path, count_of(item['count'])))

    raw_priors = expect_list(obj['priors'])
    if len(raw_priors) > MAX_PRIORS:
        raise Invalid()
    priors = {}
    for record in raw_priors:
        item = exact_keys(record, ('link', 'weights'))
        u, v = pair_of(item['link'])
        weights = expect_list(item['weights'])
        if len(weights) != 3:
            raise Invalid()
        vals = []
        for w in weights:
            if type(w) is not int or w < 0 or w > MAX_COUNT:
                raise Invalid()
            vals.append(w)
        s = vals[0] + vals[1] + vals[2]
        if s <= 0:
            raise Invalid()
        link = canonical(u, v)
        if link in priors:
            raise Invalid()
        vec = ((vals[0], s), (vals[1], s), (vals[2], s))
        priors[link] = vec if u < v else (vec[2], vec[1], vec[0])

    raw_declared = expect_list(obj['declared'])
    if len(raw_declared) > MAX_DECLARED:
        raise Invalid()
    declared = {}
    for record in raw_declared:
        item = exact_keys(record, ('link', 'rel'))
        u, v = pair_of(item['link'])
        rel = item['rel']
        if type(rel) is not str or rel not in REL_STATE:
            raise Invalid()
        link = canonical(u, v)
        if link in declared:
            raise Invalid()
        vec = one_hot(REL_STATE[rel], u < v)
        declared[link] = vec

    raw_order = expect_list(obj['order'])
    if len(raw_order) > MAX_ORDER_LEN:
        raise Invalid()
    order_links = []
    for item in raw_order:
        link = pair_of(item)
        if link[0] >= link[1]:
            raise Invalid()
        order_links.append(link)
    if len(set(order_links)) != len(order_links):
        raise Invalid()

    raw_queries = expect_list(obj['queries'])
    if len(raw_queries) > MAX_QUERIES:
        raise Invalid()
    queries = []
    ids = set()
    for record in raw_queries:
        item = exact_keys(record, ('id', 'path', 'threshold'))
        ident = item['id']
        if type(ident) is not str or not ID_RE.match(ident) or ident in ids:
            raise Invalid()
        ids.add(ident)
        path = path_of(item['path'])
        thr = expect_list(item['threshold'])
        if len(thr) != 2:
            raise Invalid()
        a = thr[0]
        b = thr[1]
        if type(a) is not int or type(b) is not int:
            raise Invalid()
        if a < 0 or a > MAX_COUNT or b < 1 or b > MAX_COUNT or a > b:
            raise Invalid()
        queries.append((ident, path, a, b))

    # ---------------- normalization ----------------
    agg = {}
    for path, count in rib_records:
        norm, looped = normalize(path, ixps)
        if looped or len(norm) < 2:
            continue
        agg[norm] = agg.get(norm, 0) + count

    all_links = set()
    for path in agg:
        prev = path[0]
        for value in path[1:]:
            all_links.add(canonical(prev, value))
            prev = value
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid()

    # ---------------- peeling ----------------
    rounds, finals = peel(agg)
    core_links = sorted(all_links - set(rounds))
    if len(core_links) > MAX_CORE_LINKS:
        raise Invalid()
    if len(order_links) != len(core_links) or set(order_links) != set(core_links):
        raise Invalid()

    # ---------------- inference ----------------
    marginals = {}
    if core_links:
        model = Model(core_links, finals)
        phis = model.build_phis()
        order_vars = [model.index[link] for link in order_links]
        check_width([list(scope) for scope, _v in phis], order_vars)
        result = infer_marginals(phis, order_vars)
        if result is None:
            return {'error': 'zero-partition'}
        for i, link in enumerate(model.links):
            marginals[link] = result[i]

    # ---------------- links output ----------------
    links_out = []
    for link in sorted(all_links):
        rnd = rounds.get(link, 0)
        if rnd == 0:
            num0, num1, num2, den = marginals[link]
            prob = [num0 / den, num1 / den, num2 / den]
        else:
            vec = priors.get(link)
            if vec is None:
                prob = [1.0 / 3.0, 1.0 / 3.0, 1.0 / 3.0]
            else:
                prob = [vec[0][0] / vec[0][1], vec[1][0] / vec[1][1],
                        vec[2][0] / vec[2][1]]
        links_out.append({'link': [link[0], link[1]], 'round': rnd,
                          'prob': [clean_float(p) for p in prob]})

    # ---------------- queries ----------------
    queries_out = []
    for ident, raw, a, b in queries:
        norm, looped = normalize(raw, ixps)
        record = {'id': ident, 'path': list(norm), 'status': 'ok',
                  'score': None, 'full': None, 'witness': None,
                  'leaked': None}
        if looped:
            record['status'] = 'loop'
            queries_out.append(record)
            continue
        n = len(norm)
        if n < 3:
            record['score'] = 1.0
            record['full'] = 1.0
            record['leaked'] = False
            queries_out.append(record)
            continue
        vectors = []
        for i in range(n - 1):
            u = norm[i]
            v = norm[i + 1]
            link, forward = key_dir(u, v)
            vec = lookup(link, forward, declared, marginals, priors)
            vectors.append(vec)
        best = None
        best_index = 0
        for i in range(n - 2):
            value = legit(vectors[i], vectors[i + 1])
            if best is None or value[0] * best[1] < best[0] * value[1]:
                best = value
                best_index = i
        num, den = best
        record['score'] = clean_float(num / den)
        record['full'] = clean_float(full_legitimacy(vectors))
        record['witness'] = best_index
        record['leaked'] = num * b < a * den
        queries_out.append(record)

    return {'version': 1, 'links': links_out, 'queries': queries_out}


def clean_float(value):
    if not math.isfinite(value):
        return 0.0
    if value < 0.0 and value > -1e-15:
        return 0.0
    if value == 0.0:
        return 0.0
    return float(value)


def lookup(link, forward, declared, marginals, priors):
    vec = declared.get(link)
    if vec is None:
        mar = marginals.get(link)
        if mar is not None:
            n0, n1, n2, den = mar
            vec = ((n0, den), (n1, den), (n2, den))
        else:
            vec = priors.get(link)
            if vec is None:
                vec = ((1, 3), (1, 3), (1, 3))
    if forward:
        return vec
    return (vec[2], vec[1], vec[0])


def check_width(scopes, order_vars):
    """Validate the declared elimination order and the width promise."""
    n = len(scopes)
    adj = [set() for _ in range(n)]
    for scope in scopes:
        for i in range(len(scope)):
            for j in range(i + 1, len(scope)):
                adj[scope[i]].add(scope[j])
                adj[scope[j]].add(scope[i])
    for var in order_vars:
        neigh = adj[var]
        if len(neigh) > MAX_NEIGHBORS:
            raise Invalid()
        for other in neigh:
            items = list(neigh)
            for x in items:
                if x != other:
                    adj[x].add(other)
                    adj[other].add(x)
            adj[other].discard(var)
        adj[var] = set()


def output(document):
    try:
        text = json.dumps(document, allow_nan=False, separators=(',', ':'))
    except (TypeError, ValueError, OverflowError):
        text = '{"error":"invalid"}'
    if len(text.encode('utf-8')) > MAX_OUTPUT_BYTES:
        text = '{"error":"invalid"}'
    sys.stdout.write(text)
    sys.stdout.write('\n')


def main():
    try:
        data = read_all()
        document = parse(data)
        answer = solve(document)
    except Invalid:
        answer = {'error': 'invalid'}
    except Broken:
        answer = {'error': 'invalid'}
    except RecursionError:
        answer = {'error': 'invalid'}
    except MemoryError:
        answer = {'error': 'invalid'}
    except (KeyError, IndexError, TypeError, ValueError, OverflowError,
            ZeroDivisionError, StopIteration, AttributeError):
        answer = {'error': 'invalid'}
    output(answer)


if __name__ == '__main__':
    main()
