def canonical(u, v):
    return (u, v) if u < v else (v, u)


def key_dir(u, v):
    """Canonical link plus True when the observed direction is canonical."""
    if u < v:
        return (u, v), True
    return (v, u), False


def normalize(raw, ixps):
    """Drop IXPs first, then collapse each maximal run of duplicates."""
    out = []
    for value in raw:
        if value in ixps:
            continue
        if out and out[-1] == value:
            continue
        out.append(value)
    return tuple(out), len(set(out)) != len(out)


# ---------------------------------------------------------------------------
# simultaneous peripheral peeling
# ---------------------------------------------------------------------------
def peel(paths):
    """paths: dict of directed normalized RIB path -> aggregated count."""
    rounds = {}
    current = dict(paths)
    step = 0
    while current:
        step += 1
        occ = {}
        for path in current:
            prev = path[0]
            for value in path[1:]:
                occ.setdefault(canonical(prev, value), []).append(path)
                prev = value
        marked = set()
        for link, plist in occ.items():
            u, v = link
            all_u = True
            all_v = True
            for path in plist:
                if path[0] != u and path[-1] != u:
                    all_u = False
                if path[0] != v and path[-1] != v:
                    all_v = False
                if not all_u and not all_v:
                    break
            if all_u or all_v:
                marked.add(link)
        if not marked:
            break
        for link in marked:
            rounds[link] = step
        nxt = {}
        for path, count in current.items():
            head_link = canonical(path[0], path[1])
            tail_link = canonical(path[-2], path[-1])
            trimmed = path
            if head_link in marked:
                trimmed = trimmed[1:]
            if tail_link in marked:
                trimmed = trimmed[:-1] if len(trimmed) > 1 else trimmed[:0]
            if len(trimmed) < 2:
                continue
            nxt[trimmed] = nxt.get(trimmed, 0) + count
        current = nxt
    return rounds, current


