                        scope.append(ctx[0])
            self.scopes[e] = tuple(scope)
            pos = {}
            for i, var in enumerate(scope):
                pos[var] = i
            table = {}
            cache = {}
            for left, right, count in self.ctx[e]:
                dims = []
                if left is not None:
                    dims.append((pos[left[0]], left[1]))
                if right is not None:
                    dims.append((pos[right[0]], right[1]))
                nd = len(dims)
                listed = cache.get(nd)
