def solve(document):
    obj = expect_dict(document)
    if len(obj) != len(TOP_KEYS):
        raise Invalid()
    for name in TOP_KEYS:
        if name not in obj:
            raise Invalid()
    if type(obj['version']) is not int or obj['version'] != 1:
        raise Invalid()

    raw_ixps = expect_list(obj['ixps'])
    if len(raw_ixps) > MAX_IXPS:
        raise Invalid()
    ixps = set()
    for value in raw_ixps:
        v = asn(value)
        if v in ixps:
            raise Invalid()
        ixps.add(v)

    raw_rib = expect_list(obj['rib'])
    if len(raw_rib) > MAX_RIB:
        raise Invalid()
    rib_records = []
    total_len = 0
    for record in raw_rib:
        item = exact_keys(record, ('path', 'count'))
        path = raw_path(item['path'])
        total_len += len(path)
        if total_len > MAX_RIB_TOTAL:
            raise Invalid()
        rib_records.append((path, weight(item['count'], 1)))

    raw_priors = expect_list(obj['priors'])
    if len(raw_priors) > MAX_PRIORS:
        raise Invalid()
    priors = {}
    for record in raw_priors:
        item = exact_keys(record, ('link', 'weights'))
        u, v = link_pair(item['link'])
        vals = expect_list(item['weights'])
        if len(vals) != 3:
            raise Invalid()
        w = [weight(x, 0) for x in vals]
        s = w[0] + w[1] + w[2]
        if s <= 0:
            raise Invalid()
        link = canonical(u, v)
        if link in priors:
            raise Invalid()
        vec = ((w[0], s), (w[1], s), (w[2], s))
        priors[link] = vec if u < v else (vec[2], vec[1], vec[0])

    raw_declared = expect_list(obj['declared'])
    if len(raw_declared) > MAX_DECLARED:
        raise Invalid()
    declared = {}
    for record in raw_declared:
        item = exact_keys(record, ('link', 'rel'))
        u, v = link_pair(item['link'])
        rel = item['rel']
        if type(rel) is not str or rel not in REL_STATE:
            raise Invalid()
        link = canonical(u, v)
        if link in declared:
            raise Invalid()
        declared[link] = one_hot(REL_STATE[rel], u < v)

    raw_order = expect_list(obj['order'])
    if len(raw_order) > MAX_ORDER:
        raise Invalid()
    order_links = []
    for item in raw_order:
        link = link_pair(item)
        if link[0] >= link[1]:
            raise Invalid()
        order_links.append(link)
    if len(set(order_links)) != len(order_links):
        raise Invalid()

    raw_queries = expect_list(obj['queries'])
    if len(raw_queries) > MAX_QUERIES:
        raise Invalid()
    queries = []
    ids = set()
    for record in raw_queries:
        item = exact_keys(record, ('id', 'path', 'threshold'))
        ident = item['id']
        if type(ident) is not str or not ID_RE.match(ident) or ident in ids:
            raise Invalid()
        ids.add(ident)
        path = raw_path(item['path'])
        thr = expect_list(item['threshold'])
        if len(thr) != 2 or type(thr[0]) is not int or type(thr[1]) is not int:
            raise Invalid()
        a, b = thr[0], thr[1]
        if a < 0 or b < 1 or a > MAX_WEIGHT or b > MAX_WEIGHT or a > b:
            raise Invalid()
        queries.append((ident, path, a, b))

    # ---- normalization and aggregation of the RIB ----
    agg = {}
    for path, count in rib_records:
        norm, looped = normalize(path, ixps)
        if looped or len(norm) < 2:
            continue
        agg[norm] = agg.get(norm, 0) + count

    all_links = set()
    for path in agg:
        prev = path[0]
        for value in path[1:]:
            all_links.add(canonical(prev, value))
            prev = value
    if len(all_links) > MAX_RIB_LINKS:
        raise Invalid()

    # ---- peeling ----
    rounds, finals = peel(agg)
    core_links = sorted(all_links - set(rounds))
    if len(core_links) > MAX_CORE_LINKS:
        raise Invalid()
    if len(order_links) != len(core_links) or set(order_links) != set(core_links):
        raise Invalid()

    # ---- exact joint inference ----
    marginals = {}
    if core_links:
        model = Model(core_links, finals)
        phis = model.build_phis()
        order_vars = [model.index[link] for link in order_links]
        check_width(phis, order_vars)
        rows = marginal_rows(phis, order_vars)
        if rows is None:
            return {'error': 'zero-partition'}
        for i, link in enumerate(model.links):
            marginals[link] = rows[i]

    # ---- link records ----
    links_out = []
    for link in sorted(all_links):
        rnd = rounds.get(link, 0)
        if rnd == 0:
            n0, n1, n2, den = marginals[link]
            prob = [finite(n0 / den), finite(n1 / den), finite(n2 / den)]
        else:
            vec = priors.get(link)
            if vec is None:
                prob = [1.0 / 3.0, 1.0 / 3.0, 1.0 / 3.0]
            else:
                prob = [finite(vec[0][0] / vec[0][1]),
                        finite(vec[1][0] / vec[1][1]),
                        finite(vec[2][0] / vec[2][1])]
        links_out.append({'link': [link[0], link[1]], 'round': rnd,
                          'prob': prob})

    # ---- query records ----
    queries_out = []
    for ident, raw, a, b in queries:
        norm, looped = normalize(raw, ixps)
        record = {'id': ident, 'path': list(norm), 'status': 'ok',
                  'score': None, 'full': None, 'witness': None,
                  'leaked': None}
        if looped:
            record['status'] = 'loop'
            queries_out.append(record)
            continue
        n = len(norm)
        if n < 3:
            record['score'] = 1.0
            record['full'] = 1.0
            record['leaked'] = False
            queries_out.append(record)
            continue
        vectors = []
        for i in range(n - 1):
            link, forward = key_dir(norm[i], norm[i + 1])
            vectors.append(lookup(link, forward, declared, marginals, priors))
        best = None
        best_index = 0
        for i in range(n - 2):
            value = triple_legitimacy(vectors[i], vectors[i + 1])
            if best is None or value[0] * best[1] < best[0] * value[1]:
                best = value
                best_index = i
        record['score'] = finite(best[0] / best[1])
        record['full'] = finite(full_legitimacy(vectors))
        record['witness'] = best_index
        record['leaked'] = best[0] * b < a * best[1]
        queries_out.append(record)

    return {'version': 1, 'links': links_out, 'queries': queries_out}


